import type { ServiceNotes } from './types';

// Long-term residential (12-month management) and leasing-only tenant placement.
//
// !! READ THIS BEFORE ADDING KEYS !!
// A key only ever renders if its city is in that service's `marketCities` array
// in src/data/serviceLines/longTerm.ts — that array, not the cities collection,
// decides which /services/{service}/{city}/ pages exist at all.
// 23 of the entries below were written and source-verified against cities that
// are NOT currently in the relevant marketCities list, so they render nothing
// today. They are kept because the research behind them is sound and they
// become live the moment a city is added to that array. They are:
//   long-term-rental-management — athens, austell, canton, covington, dacula,
//     fayetteville, gainesville, hampton, hiram, lithia-springs, locust-grove,
//     monroe-ga, newnan
//   tenant-placement — athens, austell, canton, clarkston, covington, fairburn,
//     gainesville, jonesboro, lilburn, morrow
// Everything else in this file is live.
//
// Every entry below is anchored to something an owner can go and check: the
// magistrate court that would actually hear a dispossessory for that address,
// the county rule that genuinely differs from the county next door, or the
// named institution that fills the property. Where a fact could not be verified
// against a primary source, it is not here — and where a city had no
// service-specific story at all, the key is absent on purpose.
//
// SOURCES USED (all retrieved August 2026):
//  - Fulton County Magistrate Court, Landlord Pamphlet (magistratefulton.org)
//  - Fulton County Marshal's Department, Evictions (fultoncountyga.gov)
//  - DeKalb County Magistrate Court, Dispossessory FAQs (dekalbcountymagistratecourt.com)
//  - DeKalb County Code Compliance, Apartment Complex Registrations (dekalbcountyga.gov)
//  - City of Chamblee, Apartment Code Enforcement Sweeps Program (chambleega.com)
//  - Cobb County Magistrate Court, Fees and Forms (cobbcounty.gov)
//  - Gwinnett County Magistrate Court, Dispossessory Action FAQs (gwinnettcourts.com)
//  - Gwinnett County Sheriff's Office, Eviction Process (gwinnettcountysheriff.org)
//  - Gwinnett County, International Property Maintenance Code adoption (gwinnettcounty.com)
//  - Athens-Clarke County, Dispossessory + Eviction Procedures + Common
//    Residential Ordinances (accgov.com)
//  - Magistrate Court of Rockdale County, Filing Fees rev. 6/29/2024 (rockdalecountyga.gov)
//  - Magistrate Court of Walton County, Instructions for Filing a Dispossessory
//    Warrant (waltoncountyga.gov)
//  - Cherokee County Clerk of Courts, Magistrate Fees (cherokeecourtclerk.com)
//  - Hall County, Writ of Possession FAQ (hallcounty.org)
//  - Newton County Magistrate Court, Alcovy Judicial Circuit (alcovycircuit.com)
//  - Coweta County Courts (coweta.ga.us); Henry County Magistrate Court (henrycountycourts.org)
//  - O.C.G.A. § 36-74-30 (codes.findlaw.com); O.C.G.A. §§ 15-16-21, 44-7-55 as
//    cited by the Gwinnett Sheriff
//  - Piedmont Healthcare, Northeast Georgia Health System, Clayton State
//    University, Trilith, EchoPark Speedway, Select Newton — institution sites

export const residentialNotes: ServiceNotes = {
  // ==========================================================================
  // CLARKE COUNTY
  // ==========================================================================
  'long-term-rental-management:athens': [
    `A dispossessory filed on an Athens address goes to the Magistrate Court of Athens-Clarke County, Room 240 at 325 East Washington Street. The county publishes its own numbers rather than making you call: $79 to file against one defendant and $25 for each additional named defendant, with the tenant's answer due in the clerk's hands by 5:00 p.m. on the seventh day after service. Miss that deadline as a tenant and the plaintiff can file a Request for Default and Writ of Possession.`,
    `The part owners never budget for arrives after the writ. Athens-Clarke County charges the Sheriff's Office $25 per writ before it will even schedule the eviction, and it states plainly that the plaintiff or the plaintiff's agent must provide the eviction crew — roughly two workers per bedroom, and enough of them to finish inside two hours. Turn up short-handed and the deputy cancels on the spot, the eviction is rescheduled, and the $25 is charged again. Budgeting for a labor crew is part of the file here, not an afterthought.`,
    `The zoning code also reaches inside the tenancy in a way it does not elsewhere in our service area. Athens-Clarke County defines a family by blood, marriage, adoption or foster care, and in Single-Family Residential (RS) districts a dwelling may not house more than two unrelated individuals — a resident family may add only one unrelated person. On a four-bedroom near campus that rule, not the market, decides how the lease can be structured. We check the zoning district before we set a rent, not after.`,
  ],
  'tenant-placement:athens': [
    `Placement in Athens starts with a zoning question, not a marketing one. Athens-Clarke County's occupancy rule for Single-Family Residential (RS) districts allows no more than two unrelated individuals in a dwelling, and permits a resident family only one unrelated person alongside it. That single ordinance rules out the obvious way to fill a large house near campus — four unrelated students on one lease — anywhere it applies. We confirm the district for the address first, because it determines the shape of the tenancy, the size of the applicant pool, and the rent you can honestly expect.`,
    `It also means Athens is really two leasing markets sitting on top of each other. Purpose-built student communities compete on beds and per-person pricing; the houses and duplexes in the RS neighborhoods compete for households. Owners who price against the wrong one are the owners who sit vacant. We market to the pool the property is legally able to house.`,
    `The steadier applicants are the ones with no academic calendar at all. Piedmont Athens Regional Medical Center at 1199 Prince Avenue is a 427-bed regional referral center serving communities in 17 counties, St. Mary's runs a second hospital system in town, and the Athens-Clarke County unified government is an employer in its own right. Those renters want a twelve-month lease that does not turn over every August, and they are worth writing the listing for.`,
  ],

  // ==========================================================================
  // ROCKDALE COUNTY
  // ==========================================================================
  'long-term-rental-management:conyers': [
    `Conyers is the county seat, so the court that would hear a dispossessory on your property is a few minutes from it: the Magistrate Court of Rockdale County at 874 N. Main Street NW. Rockdale publishes a fee schedule and keeps it dated — the current one took effect July 1, 2024 — which makes it one of the easier metro counties to budget an enforcement action against. A dispossessory warrant costs $75.00, each additional named defendant is $25.00, and the dispossessory writ of possession is a separate $25.00.`,
    `That last line is the one owners miss. Winning the case and taking possession are two different filings with two different fees, and the writ is what actually moves anybody out. We treat the writ as part of the plan from the day the first late notice goes out, not as a surprise at the end.`,
    `On the regulatory side, Rockdale looks light and mostly is — Georgia's O.C.G.A. § 36-74-30(b) bars any local government from requiring the registration of residential rental property, and limits code inspections of a rental to cases where there is probable cause to believe a violation exists. What that leaves is complaint-driven enforcement, which is exactly why scheduled interior inspections matter more here than in a county that inspects for you. Nobody is going to tell you the water heater is weeping. Documented, photographed inspections are how you find out first.`,
  ],
  'tenant-placement:conyers': [
    `Conyers sits on I-20 between Atlanta and Covington, which shapes who applies. The applicant pool leans toward households who need the interstate — commuters splitting the difference between an intown job and a house they can afford, and workers in the warehousing and light-manufacturing employment along the corridor. That pool responds to commute time and condition far more than to finishes, and pricing a Conyers house as though it competes with an intown rental is the reliable way to sit empty.`,
    `Placement here also carries a specific tail. Because Conyers is the Rockdale County seat, any future enforcement runs through the Magistrate Court of Rockdale County at 874 N. Main Street NW — where the published schedule effective July 1, 2024 sets a dispossessory warrant at $75.00 plus $25.00 per additional named defendant, and a further $25.00 for the writ of possession. We name every adult occupant on the lease for exactly that reason: an unnamed occupant discovered later is a defendant you have not paid for and a case that can stall.`,
    `And because Georgia's O.C.G.A. § 36-74-30(b) forbids local rental registration and confines inspections to probable-cause cases, no county inspector is going to pre-screen the property for you before a tenant moves in. The written, photographed move-in condition record we hand over is the only baseline that will exist.`,
  ],

  // ==========================================================================
  // NEWTON COUNTY
  // ==========================================================================
  'long-term-rental-management:covington': [
    `A dispossessory on a Covington address is heard by the Newton County Magistrate Court, part of the Alcovy Judicial Circuit, which handles civil claims up to $15,000 alongside its landlord-tenant docket. That jurisdictional ceiling matters more than owners expect: unpaid rent, late fees and damage on a long tenancy can run past $15,000, and when they do the money claim and the possession claim can end up on different tracks. Keeping a clean, current ledger from month one is what keeps that decision simple later.`,
    `Newton County's rental demand is industrial in a way most of the eastern metro is not. Newton County's own economic development office describes the county as a place where "advanced manufacturing, bioscience, film and entertainment" grow, and names Takeda, General Mills, Bridgestone, Michelin, Meta, Archer Aviation and Rivian among the employers on the ground. Shift work at plants like those produces a specific renter: stable income, non-standard hours, and a strong preference for a house within a short drive of the gate rather than a commute into Atlanta.`,
    `Piedmont Newton Hospital at 5126 Hospital Drive NE — a 107-bed acute care community hospital that has served Newton County for over 70 years, by Piedmont's own account — adds the other half of that base. Between the plants and the hospital, Covington's twelve-month demand is far less tied to Atlanta's office cycle than the surrounding counties, and we price and market accordingly.`,
  ],
  'tenant-placement:covington': [
    `The Covington applicant pool is built on payroll, not commuting. Newton County's economic development office lists Takeda, General Mills, Bridgestone, Michelin, Meta, Archer Aviation and Rivian among the employers here, and describes the county's economy as advanced manufacturing, bioscience, and film and entertainment. Plant and data-center employment produces applicants with verifiable, steady income and shift schedules — which changes how showings should be run. Evening-and-weekend-only showing windows quietly exclude a large part of your best pool.`,
    `Piedmont Newton Hospital on Hospital Drive NE is the other anchor, a 107-bed acute care community hospital that has served the county for more than 70 years. Healthcare and plant households are the two groups most likely to renew, and both screen well against a written income standard.`,
    `One practical note on the paperwork. Covington is a genuine production location and short-term film housing circulates here, which means some owners arrive at placement with a furnished, nightly-let property and a habit of informal agreements. A twelve-month unfurnished lease is a different instrument: it needs the Georgia disclosures, a signed and photographed existing-damage list before the deposit is accepted, and every adult occupant named. We do that work at the front end because the Newton County Magistrate Court, if it ever sees the file, will be reading exactly those documents.`,
  ],

  // ==========================================================================
  // WALTON COUNTY
  // ==========================================================================
  'long-term-rental-management:monroe-ga': [
    `Walton County runs one of the most explicitly documented dispossessory processes in the metro, and its instructions are worth reading before you ever need them. The Magistrate Court sits at 303 South Hammond Drive, Suite 116 in Monroe. The filing fee is $101.00, due at the time of filing. The court will not accept a post office box as the defendant's address — a real physical address is mandatory, which quietly punishes owners who never collected one.`,
    `Three further rules shape strategy here. A default judgment is not issued automatically: you may request one eight days after service, and that request must be made in writing by the plaintiff, an agent for the plaintiff, or an attorney. A money judgment cannot be obtained on tack-and-mail service unless the tenant answers or appears — so if service was posted to the door, the rent you are owed may not come with the possession you win. And the court states that it generally will not issue consent judgments in dispossessory actions, which removes the "sign this and stay" workaround owners lean on in other counties.`,
    `There is no court fee for issuing the writ of possession itself; the Walton County Sheriff's Department bills separately for serving it. Monroe's twelve-month base includes Piedmont Walton Hospital at 2151 West Spring Street — a 77-bed acute care hospital and, per Piedmont, the only hospital provider in Walton County offering 24-hour emergency services — which anchors a steady healthcare-household renter pool in a county otherwise built on commuting.`,
  ],

  // ==========================================================================
  // HALL COUNTY
  // ==========================================================================
  'long-term-rental-management:gainesville': [
    `Hall County publishes the part of the eviction most owners have never priced. Once a writ of possession issues, you bring it to the Sheriff's Office on the ground floor of the Hall County Courthouse or mail it to 225 Green St SE in Gainesville with a $25 check, and evictions are scheduled first-come, first-served. Crucially, Hall County tells landlords to bring their own workforce — at least two people per bedroom for a residential eviction — because deputies do not assist with physically removing property. For a four-bedroom house that is eight people you are responsible for hiring, on a date the Sheriff sets.`,
    `Gainesville's rental demand is unusually independent of Atlanta. Northeast Georgia Medical Center's Gainesville campus at 743 Spring Street anchors a health system that, by its own account, cares for almost a million people across more than 18 counties, and Hall County's poultry-processing economy runs on shift labor that rents rather than buys. Those two facts together produce a renter profile — steady, local, non-commuting — that behaves very differently from a metro bedroom community, and it holds up when Atlanta's office market wobbles.`,
    `Because Georgia's O.C.G.A. § 36-74-30(b) prohibits local governments from requiring registration of residential rental property and limits inspections to probable-cause situations, nothing external will flag a maintenance problem for you here. Scheduled, photographed interior inspections are the only early-warning system a Hall County owner actually has.`,
  ],
  'tenant-placement:gainesville': [
    `Gainesville leases to people who work here, which is the single most useful thing to know when pricing a vacancy. Northeast Georgia Medical Center's Gainesville campus on Spring Street anchors a health system serving almost a million people across more than 18 counties, and Hall County's poultry-processing industry employs on shifts. Applicants from both groups verify well on income and prior-landlord history, and both value proximity to the plant or the hospital over almost anything else — which means the right comparable for your property is another Gainesville rental, not a Gwinnett one.`,
    `Shift work also changes the mechanics of a placement. Showings that only run at 6pm on a weekday miss half of this pool, and employment verification often means a plant HR line rather than a manager's cell phone. We build the showing schedule and the verification path around that instead of expecting applicants to work around us.`,
    `Worth knowing before you hand the tenancy back: if enforcement ever becomes necessary, Hall County requires the landlord to supply the eviction labor — at least two people per bedroom, because deputies do not assist with removing property — and charges $25 to schedule the writ. Placement is the moment to get the file right, because the cost of getting it wrong in Hall County is measured in hired hands.`,
  ],

  // ==========================================================================
  // COWETA COUNTY
  // ==========================================================================
  'long-term-rental-management:newnan': [
    `Newnan is the Coweta County seat, and a dispossessory on a Newnan address is heard at the Magistrate Court in the Justice Center at 72 Greenville Street. Coweta runs its magistrate filings through an electronic filing portal rather than a paper counter, which is straightforward once you are enrolled and a genuine obstacle at 4:45pm on the day a case needs to go in. Being already set up to file is part of what a manager is for.`,
    `Piedmont Newnan Hospital at 745 Poplar Road is the demand anchor that separates Newnan from the commuter towns around it. Piedmont describes it as a 217-bed acute care, not-for-profit community hospital and the only acute care facility in Coweta County. A single hospital serving an entire county produces a large, permanent, locally-employed renter base — nurses, technicians, therapists, administrative staff — who need twelve-month housing near the campus and who are not commuting to Atlanta at all.`,
    `Georgia's O.C.G.A. § 36-74-30(b) prevents Coweta, like every Georgia county, from requiring residential rental registration, and confines code inspections of a rental to cases with probable cause of a violation. So there is no county-run safety net checking your property between tenants. Scheduled interior and exterior inspections with photographs are the substitute, and on a house held for years they are the difference between planned spending and an emergency invoice.`,
  ],
  'tenant-placement:newnan': [
    `The Newnan applicant pool is anchored by one institution more than any other. Piedmont Newnan Hospital at 745 Poplar Road is, by Piedmont's own description, a 217-bed acute care community hospital and the only acute care facility in Coweta County. That concentration produces a reliable, locally-employed renter — clinical and support staff who want a short drive to the campus, verify cleanly on income, and tend to renew rather than move. Marketing a Newnan rental as an Atlanta commuter option usually prices it against the wrong competition.`,
    `The second thing to know is the channel. A meaningful share of relocating clinical staff arrive with an agent, and agents search the MLS. A Newnan house listed only on consumer portals never reaches the people being recruited into the hospital, which in a county with one acute care facility is a large fraction of the incoming households each year.`,
    `Set the file up for Coweta's court while you still have everybody's attention. A dispossessory here is heard at the Magistrate Court in the Justice Center at 72 Greenville Street and filed electronically, so the details that stall a case — a missing adult occupant, an address without a unit number, a lease nobody countersigned — are worth fixing on signing day rather than a year later.`,
  ],

  // ==========================================================================
  // FAYETTE COUNTY
  // ==========================================================================
  'long-term-rental-management:fayetteville': [
    `Fayetteville's rental demand has two engines, and they pull on different schedules. Piedmont Fayette Hospital at 1255 Highway 54 West is a 310-bed acute care hospital serving Fayetteville and the surrounding counties, which produces the steady, twelve-month, locally-employed household that a long-term rental is built for. Trilith — the 234-acre studio and residential development in Fayetteville, with roughly 1,400 planned front doors and half its land preserved as greenspace — produces something quite different: production-linked demand that arrives in waves and leaves again.`,
    `That split is the strategic question on almost every Fayetteville property we look at. A house priced and furnished for production crews chases a market that can go quiet between projects; the same house on a twelve-month unfurnished lease to a hospital household earns less per night and far more per year, with a fraction of the operating load. We will model both honestly, including the cases where the property genuinely belongs on the short-term side.`,
    `A dispossessory on a Fayetteville address is heard by the Fayette County Magistrate Court in Fayetteville, and Georgia's O.C.G.A. § 36-74-30(b) means the county cannot require you to register the rental or inspect it absent probable cause of a violation. The practical consequence is the same everywhere in Georgia and worth repeating: the only condition record that will exist is the one you create, signed and photographed, before the deposit is accepted.`,
  ],
  'tenant-placement:fayetteville': [
    `Fayetteville places well because it has a large employer that recruits continuously. Piedmont Fayette Hospital on Highway 54 West is a 310-bed acute care hospital serving Fayetteville and surrounding counties, and hospital hiring produces exactly the applicant a leasing-only owner wants: verifiable income, a documented employment history, and a reason to stay put. Those households are also the ones most likely to be working with an agent when they relocate, which is why the MLS listing matters more here than the portal listing.`,
    `The competing inventory is the wrinkle. Trilith's 234-acre development in Fayetteville, with around 1,400 planned front doors, has added a large block of newer housing with its own rental activity, and it sets a visible quality benchmark for the whole submarket. An older Fayetteville house does not have to beat it — but the asking rent has to acknowledge that a prospective tenant has probably just walked through something newer the same afternoon. Condition and photography carry disproportionate weight here.`,
    `We price against what has actually leased rather than what is listed, and we tell you on day one if the number you have in mind is above what the evidence supports. In a submarket with new supply visible from the road, that conversation is cheaper before the listing goes live than six weeks into a vacancy.`,
  ],

  // ==========================================================================
  // CHEROKEE COUNTY
  // ==========================================================================
  'long-term-rental-management:canton': [
    `Canton is the Cherokee County seat, which means the court that would hear a dispossessory on your property is in your own town rather than an hour's drive away. Cherokee also bundles its fees in an unusually clear way: the Clerk of Courts lists a Petition for Writ of Dispossessory at $86.00, and that figure already includes the Sheriff's service on one defendant, with $25.00 for each additional tenant served. Most metro counties split that into two or three separate line items you discover one at a time.`,
    `The practical lesson is about naming, not money. Because service is priced per tenant, every adult who actually lives in the house needs to be on the lease and on the affidavit. An unnamed adult occupant found at the door is the most common reason a Georgia dispossessory has to be amended and re-served, and in Cherokee that shows up directly on the invoice.`,
    `Georgia's O.C.G.A. § 36-74-30(b) bars Cherokee County — like every local government in the state — from requiring registration of residential rental property, and confines inspections to cases with probable cause of a code violation. In a county growing as quickly as this one, that puts the entire burden of knowing your property's condition on scheduled, photographed inspections. Owners who only hear from a manager when something breaks are, by definition, hearing about it late.`,
  ],
  'tenant-placement:canton': [
    `Canton's applicant pool is shaped by its position at the top of the metro: far enough out that the rent buys real space, close enough to I-575 that a household can still commute. That combination attracts families rather than singles, which changes what a placement should optimize for. Bedroom count, a usable yard, and school attendance zone move the rent here far more than a renovated kitchen does — and families sign longer leases, which is the whole economic case for a leasing-only engagement.`,
    `Timing follows the school calendar rather than the corporate one. Families relocating for a school year are looking earlier and deciding faster than the market's general rhythm suggests, and a property that is rent-ready and photographed before that window is competing against far less.`,
    `Get the lease right for Cherokee's court while you can. A dispossessory on a Canton address is filed with the Cherokee County Magistrate Court and the Clerk lists the Petition for Writ of Dispossessory at $86.00 including the Sheriff's service on one defendant, plus $25.00 for each additional tenant served. That pricing is a direct argument for naming every adult occupant on the lease at signing — the cheapest moment to get the roster right is the day the keys change hands, not the day you need the court.`,
  ],

  // ==========================================================================
  // CLAYTON COUNTY
  // ==========================================================================
  'long-term-rental-management:morrow': [
    `Morrow's twelve-month rental demand has a specific and often-misattributed source: Clayton State University is in Morrow, at 2000 Clayton State Boulevard — not in Jonesboro, where people tend to assume it sits. A four-year university inside the city limits produces year-round demand for unfurnished twelve-month housing from staff, faculty, graduate students and the families of students, which is a steadier base than the retail and logistics employment the wider south metro is known for.`,
    `A dispossessory on a Morrow address is heard by the Clayton County Magistrate Court in Jonesboro, the county seat, and Clayton runs dispossessory filings electronically. The practical implication for an owner is timing: electronic filing removes the drive but not the preparation, and a case still fails on the same things it always did — a demand for possession that was never made, an address without a unit number, an adult occupant nobody named.`,
    `Georgia's O.C.G.A. § 36-74-30(b) prevents Clayton County from requiring registration of residential rental property and limits inspections of a rental to probable-cause situations. That leaves the condition of your asset entirely in the hands of whoever is inspecting it on a schedule. On south metro single-family stock, where a large share of houses are held as rentals by owners who are not local, that scheduled photo record is frequently the only current information anyone has about the property.`,
  ],
  'tenant-placement:morrow': [
    `Placement in Morrow benefits from an anchor most south metro cities do not have. Clayton State University sits inside the city at 2000 Clayton State Boulevard, and a university generates applicants on a rhythm of its own — staff and faculty hires, graduate students, and families of students — separate from the retail and distribution employment across the rest of Clayton County. That pool is worth writing the listing for explicitly, because it renews and it verifies cleanly.`,
    `The competing inventory here is mostly scattered single-family houses held as rentals rather than large managed apartment communities, and that matters for how you price. Scattered rentals are inconsistent in condition, so a genuinely rent-ready house with real photography stands out immediately in a way it would not in a submarket dominated by professionally managed communities. Condition is the cheapest competitive advantage available in Morrow.`,
    `Because Georgia's O.C.G.A. § 36-74-30(b) forbids local rental registration and confines inspections to probable-cause cases, no inspector will document the property before the tenant moves in. The signed, photographed existing-damage list we complete before the deposit is accepted is the only baseline that will exist — and on a self-managed property it is the document that decides a deposit dispute a year later.`,
  ],
  'long-term-rental-management:jonesboro': [
    `Jonesboro is the Clayton County seat, so the Magistrate Court that would hear a dispossessory on your property is here rather than somewhere you have to drive to. Clayton handles dispossessory filings electronically, which shortens the mechanics and shifts the risk to preparation: the file has to be right before it is submitted, because there is no clerk at a counter catching a missing unit number or an unnamed adult occupant.`,
    `Owning a rental in Jonesboro also means owning it in a submarket where a large share of single-family houses are held as rentals by non-local owners. That has two consequences worth planning for. Comparable condition is inconsistent, so a well-maintained house genuinely outperforms rather than merely competing. And vendor relationships matter more than usual, because the trades in this part of the metro are stretched across a lot of absentee-owned inventory.`,
    `Georgia's O.C.G.A. § 36-74-30(b) bars Clayton County from requiring registration of residential rental property and limits inspections to cases with probable cause of a code violation. There is no county programme quietly checking your asset between tenants. Scheduled interior and exterior inspections with photographs are the only mechanism that catches the slow problems — a weeping supply line, an unauthorised occupant, a failing HVAC — before they become the expensive version of themselves.`,
  ],
  'tenant-placement:jonesboro': [
    `The Jonesboro leasing market is dominated by scattered single-family rentals rather than large professionally managed apartment communities, and that shapes the entire placement strategy. Condition across the competing inventory is uneven, which means a house that is genuinely rent-ready — clean, photographed properly, priced against what has actually leased — is not competing on equal terms. It is competing against listings that were photographed on a phone. That gap is the single cheapest advantage available to a Jonesboro owner.`,
    `It also means the applicant pool is used to being screened casually, and reacts well to being screened properly. A written standard applied identically to everyone, with prior landlords actually telephoned rather than emailed a form, filters this market more sharply than it does in a submarket where every applicant has already passed through an institutional leasing office.`,
    `One thing to settle at signing rather than later. Any future dispossessory on the property is filed with the Clayton County Magistrate Court here in Jonesboro and submitted electronically, and the failures that stall those cases are almost always documentary — an adult occupant who was never named on the lease, an address recorded without its unit number, a demand for possession nobody can evidence. We close those gaps on the day the lease is executed.`,
  ],

  // ==========================================================================
  // HENRY COUNTY
  // ==========================================================================
  'long-term-rental-management:mcdonough': [
    `McDonough is the Henry County seat, and a dispossessory on a McDonough address is heard at the Henry County Magistrate Court, 44 John Frank Ward Boulevard, Suite 260. Henry accepts small claims, dispossessory actions, answers and writ of possession applications through an online filing system, which is genuinely useful — and which makes the quality of the underlying file the only remaining variable. Georgia still requires a proper written demand for possession before a dispossessory can be filed, and an online portal will happily accept a case that has no evidence one was ever made.`,
    `The city describes itself as "the center for activities, art, and commerce for Henry County and the southern arc of Metro Atlanta," and the rental demand reflects that: a county-seat mix of government, courts, professional services and retail employment, plus the I-75 logistics corridor running alongside it. Worth knowing that Henry County's acute care hospital, Piedmont Henry, is at 1133 Eagles Landing Parkway in Stockbridge rather than in McDonough — so a large healthcare workforce lives in McDonough and commutes a few miles north, which is precisely the household a twelve-month lease is designed for.`,
    `Georgia's O.C.G.A. § 36-74-30(b) prevents Henry County from requiring registration of residential rental property or inspecting a rental without probable cause of a violation. Nothing external will tell you how the house is holding up. Scheduled photo inspections are the substitute, and on newer suburban stock they matter more than owners expect — construction-era defects surface in years five to ten, quietly, behind finished walls.`,
  ],
  'tenant-placement:mcdonough': [
    `McDonough's applicant pool is broader than its size suggests because it is the Henry County seat. The city describes itself as "the center for activities, art, and commerce for Henry County and the southern arc of Metro Atlanta," and county-seat employment — courts, county government, professional services — sits alongside the I-75 logistics corridor. A second large group commutes a few miles north to Piedmont Henry Hospital at 1133 Eagles Landing Parkway in Stockbridge, which is the county's acute care facility and is not in McDonough at all.`,
    `Those healthcare and government households are the ones worth writing the listing for. They verify cleanly against a written income standard, they are relocating for a specific job rather than shopping speculatively, and they sign twelve months without negotiating hard on term.`,
    `Set the file up for the court you would actually use. A dispossessory on a McDonough address is filed with the Henry County Magistrate Court at 44 John Frank Ward Boulevard, Suite 260, and Henry accepts dispossessory filings, answers and writ applications online. What an online portal cannot fix is a missing written demand for possession, an unnamed adult occupant, or an address recorded without its unit number — so we fix those at signing, when everyone is still in the room.`,
  ],
  'long-term-rental-management:stockbridge': [
    `Stockbridge holds the piece of infrastructure the rest of Henry County commutes to. Piedmont Henry Hospital is here, at 1133 Eagles Landing Parkway — by Piedmont's own description a 259-bed, not-for-profit acute care hospital that has served Henry County and the surrounding areas for over 40 years, with more than 1,200 physicians and 1,900 healthcare professionals. A hospital of that size inside the city limits produces exactly the tenant a twelve-month unfurnished lease is built for: locally employed, shift-scheduled, and looking for a short drive rather than a commute into Atlanta.`,
    `The court is not here, though. A dispossessory on a Stockbridge address is heard by the Henry County Magistrate Court at 44 John Frank Ward Boulevard, Suite 260 in McDonough, the county seat, which accepts dispossessory actions, answers and writ of possession applications through an online filing system. The portal saves the drive; it does not save a file that is missing a written demand for possession, which Georgia requires before a nonpayment case can be filed at all.`,
    `Georgia's O.C.G.A. § 36-74-30(b) prevents Henry County from requiring registration of residential rental property and confines inspections of a rental to cases with probable cause of a violation. Nothing external is watching your asset between tenancies. On the newer subdivision stock that makes up much of Stockbridge's rental supply that matters more than owners assume, because construction-era defects tend to surface quietly in years five to ten — behind finished walls, where only a scheduled photo inspection will find them.`,
  ],
  'tenant-placement:stockbridge': [
    `Stockbridge places well because the largest employer is inside the city rather than an hour up the interstate. Piedmont Henry Hospital at 1133 Eagles Landing Parkway is a 259-bed acute care hospital that has served Henry County for over 40 years, with more than 1,200 physicians and 1,900 healthcare professionals by Piedmont's own account. Clinical and support staff are the applicants worth writing the listing for: they verify cleanly against a written income standard, they are relocating for a specific job, and they renew.`,
    `Shift work changes the logistics of a placement, and owners lose good applicants by ignoring it. Showings offered only on weekday evenings quietly exclude a large part of this pool, and employment verification often runs through a hospital HR line rather than a manager's mobile. We build the schedule and the verification path around the way these households actually work.`,
    `Two things to settle before handing the tenancy back. A dispossessory on a Stockbridge address goes to the Henry County Magistrate Court at 44 John Frank Ward Boulevard, Suite 260 in McDonough, which takes filings online — but Georgia still requires a written demand for possession before a nonpayment case can be filed, and no portal will supply one after the fact. And because O.C.G.A. § 36-74-30(b) bars the county from requiring rental registration or inspecting without probable cause, the signed and photographed move-in condition record is the only independent documentation your property will ever have.`,
  ],
  'long-term-rental-management:hampton': [
    `A dispossessory on a Hampton address is heard at the Henry County Magistrate Court, 44 John Frank Ward Boulevard, Suite 260 in McDonough, which accepts dispossessory actions, answers and writ of possession applications through an online filing system. Convenient, but it does not soften Georgia's prerequisites: a written demand for possession still has to have been made and evidenced before the case is filed, and that is the step self-managing owners most often skip.`,
    `Hampton's best-known landmark changed its name recently, which is a useful test of whether anyone writing about this market is paying attention: the track long known as Atlanta Motor Speedway was renamed EchoPark Speedway on June 3, 2025. For a long-term rental that matters less than it sounds. Race weekends drive nightly demand, not twelve-month demand — the households that actually sign year-long leases in Hampton are commuting to jobs along the I-75 corridor and to Piedmont Henry Hospital in Stockbridge, and they want a quiet street and a short drive, not event proximity.`,
    `Because Georgia's O.C.G.A. § 36-74-30(b) bars Henry County from requiring rental registration or inspecting without probable cause, the only condition record on a Hampton rental is the one the owner creates. Scheduled photo inspections, plus a signed existing-damage list taken before the deposit is accepted, are what turn a deposit dispute into a short conversation instead of a long one.`,
  ],
  'long-term-rental-management:locust-grove': [
    `Locust Grove sits on the I-75 logistics spine of Henry County, and its twelve-month rental demand follows the warehouses rather than Atlanta's office cycle. That produces a durable renter — distribution, transport and retail employment with regular hours and verifiable income — and a specific operational reality: shift schedules mean maintenance access and showings have to be arranged around people who are not home between nine and five.`,
    `A dispossessory on a Locust Grove address goes to the Henry County Magistrate Court at 44 John Frank Ward Boulevard, Suite 260 in McDonough, which takes dispossessory filings, answers and writ of possession applications online. The county's acute care hospital, Piedmont Henry, is at 1133 Eagles Landing Parkway in Stockbridge — around twenty minutes up the interstate — so healthcare households live here too and commute north.`,
    `Georgia's O.C.G.A. § 36-74-30(b) prevents any Georgia local government from requiring registration of residential rental property, and limits code inspections of a rental to cases where there is probable cause of a violation. On the newer subdivision stock that makes up much of Locust Grove's rental supply, that absence of external oversight is easy to mistake for an absence of risk. Scheduled interior inspections with photographs are how an owner learns about a slow leak or an unauthorised occupant while it is still cheap.`,
  ],

  // ==========================================================================
  // COBB COUNTY
  // ==========================================================================
  'long-term-rental-management:marietta': [
    `Marietta is the one Cobb city that runs its own housing code, and owners routinely miss it. The City of Marietta operates a Residential Housing Code program whose stated job includes inspecting "dwelling units for compliance with the basic minimum housing standards deemed essential for safe and healthful living," issuing notices of noncompliance to owners in violation, issuing notices of condemnation on unfit dwellings, and preparing municipal-court-ordered demolitions — with liens placed on court-ordered demolitions if not paid within 30 days. The city also states flatly that all residences must be equipped with a smoke detector.`,
    `Just as important is what does not apply. Cobb County's tenant housing-complaint process is expressly limited to "rental property located within unincorporated Cobb County," so a Marietta rental sits outside it entirely; the city's own code enforcement handles it instead, and Marietta's division notes it can only investigate complaints inside the city limits. Two enforcement systems, one county, and the city line decides which one your tenant can call.`,
    `A dispossessory on a Marietta address goes to the Cobb County Magistrate Court at 32 Waddell Street, right here in town, where dispossessory hearings are held on Tuesdays at 9 a.m. and 1:30 p.m. and the tenant has seven days from service to answer. Cobb also runs an off-duty eviction route: if the Sheriff cannot execute within 14 days of the writ being scheduled, a landlord may apply — in person, at 185 Roswell Street, at least five days before the intended execution — to have certified off-duty peace officers carry it out, at the landlord's cost.`,
  ],
  'tenant-placement:marietta': [
    `Marietta is a genuinely renter-weighted market, and the city's own adopted comprehensive plan says so: the renter share of households rose from 55% in 2010 to 56% in 2019 while vacancy fell from 13% to 9%. The same plan describes a stock that is only about 41% single-family, with the rest split fairly evenly between missing-middle, small-to-mid multifamily and larger multifamily. That is unusual for Cobb, and it means a single-family rental here is priced against apartment inventory as much as against other houses.`,
    `The demand behind it is institutional and walk-to-work in character. Wellstar Kennestone Regional Medical Center sits at 677 Church Street NE, Kennesaw State University's Marietta Campus at 1100 South Marietta Pkwy, Life University at 1269 Barclay Circle, and Chattahoochee Technical College runs two campuses in the city. Those are employers and schools that recruit continuously, which is a steadier source of applicants than commuter demand.`,
    `One boundary matters more than any amenity when a family is choosing: Marietta City Schools is a separate district with its own board of education, headquartered at 250 Howard Street, and it does not follow Cobb County lines. Getting the attendance zone right in the listing is not a nice-to-have here — it is the first question a relocating household asks, and the wrong answer costs weeks of vacancy.`,
  ],
  'long-term-rental-management:austell': [
    `Austell's rental stock changed fast, and the city documented it. Austell's adopted comprehensive plan records that between 2010 and 2019 the city saw a 17.6% increase in owner-occupied rates, a 31.6% increase in rental rates, and a 44.6% increase in vacancy rates, while the overall housing stock grew 23.7% — 564 units. Rental demand and rental supply both grew, which is precisely the condition in which an overpriced or poorly presented unit sits empty while the market looks healthy in aggregate.`,
    `The plan also puts a number on who your tenant is: the median income of renters in Austell was $57,007 against $122,643 for owners. That gap is the whole argument for screening to a written income standard rather than by feel, and for pricing against what has actually leased instead of what the owner hopes.`,
    `Code enforcement here is complaint-driven and deliberately non-anonymous. Austell's code enforcement covers nuisance conditions — overgrowth, abandoned vehicles, outside storage, structures in disrepair, noise — and the city states that a form not signed by the complainant will not be acted upon, and that any form signed anonymously will not be acted upon either. Nothing proactively inspects your property. Wellstar Cobb Medical Center at 3950 Austell Road and Chattahoochee Technical College's Austell campus on Veterans Memorial Highway anchor the local employment base a twelve-month lease is written against.`,
  ],
  'tenant-placement:austell': [
    `Price an Austell vacancy against evidence, not optimism. The city's own comprehensive plan records that between 2010 and 2019 rental rates rose 31.6% — but vacancy rose 44.6% over the same period, and the housing stock grew 23.7%. A market can add renters and add empty units at the same time, and that is exactly the condition where a listing priced on hope quietly loses six weeks.`,
    `The plan also reports a median renter income of $57,007 against $122,643 for owners. That is not a reason to lower standards; it is a reason to have written ones. A documented income threshold, prior landlords telephoned directly, and public-record review applied identically to every applicant is what separates a tenant who is still paying in month fourteen from one who was approved because the vacancy felt expensive.`,
    `Two employers anchor the applicant pool worth marketing to: Wellstar Cobb Medical Center at 3950 Austell Road, and Chattahoochee Technical College's Austell campus at 1578 Veterans Memorial Hwy. Hospital and college households verify cleanly, tend to renew, and are reachable through an agent channel — which is one concrete reason the property belongs on the MLS as well as the consumer portals.`,
  ],
  'long-term-rental-management:kennesaw': [
    `Kennesaw State University's main campus sits inside the city at 1000 Chastain Road, and a university of that scale — KSU publishes an enrolment of 51,000-plus students across its campuses — reshapes what a twelve-month unfurnished rental is competing for. Staff, faculty, graduate students and the families of students all want year-round housing that does not follow the undergraduate calendar, and that is a materially different tenancy from the bed-by-bed student market surrounding it.`,
    `Because Kennesaw is an incorporated city, Cobb County's tenant housing-complaint process does not reach it — the county limits that process to "rental property located within unincorporated Cobb County." Combined with O.C.G.A. § 36-74-30(b), which bars any Georgia local government from requiring registration of residential rental property and confines inspections to probable-cause cases, the practical position is that no external body is monitoring the condition of your Kennesaw rental. Scheduled, photographed inspections are the whole early-warning system.`,
    `A dispossessory on a Kennesaw address is heard by the Cobb County Magistrate Court at 32 Waddell Street in Marietta, with hearings on Tuesdays at 9 a.m. and 1:30 p.m. and a seven-day window for the tenant to answer. Cobb notes that a landlord must have made a demand for possession before proceedings begin — the step self-managing owners most often cannot evidence when it matters.`,
  ],
  'tenant-placement:kennesaw': [
    `Kennesaw's applicant pool is dominated by one institution and it is worth marketing to deliberately. Kennesaw State University's campus at 1000 Chastain Road is inside the city, and KSU publishes an enrolment of 51,000-plus students. The households a twelve-month unfurnished lease actually wants from that ecosystem are the ones off the undergraduate cycle — staff, faculty, postgraduates, visiting researchers, and families of students — who sign for a year and renew rather than turning over each August.`,
    `That distinction should drive the listing copy and the timing. A house presented as student housing attracts per-room enquiries, short terms and the operational load that comes with them. The same house presented as a family or professional home, photographed properly and priced against what comparable houses have leased for, reaches a different and steadier pool.`,
    `Set the paperwork up for the court that would hear it later. A dispossessory on a Kennesaw address goes to the Cobb County Magistrate Court at 32 Waddell Street in Marietta, and Cobb requires that a demand for possession have been made before proceedings begin. We build the lease and the notice trail so that requirement is already satisfied and evidenced on day one, then hand you the file.`,
  ],
  'long-term-rental-management:mableton': [
    `Mableton is the single most misunderstood address in our long-term portfolio, because the rules changed underneath it. The city's own account is that it was incorporated in November 2022, that it is the largest city in Cobb County with a population of nearly 80,000, and that its charter gives it authority over business licensing, building permits, inspections, zoning and planning, and code enforcement. Police, fire, roads, streetlights, animal services and schools all remain Cobb County's.`,
    `The handover has a date on it. Cobb County announced that starting March 3, 2025, the City of Mableton assumed all zoning and code enforcement services within its city limits, with only some special regulatory permits — notably those for businesses selling alcohol — still coming through the county. Any guidance that still routes a Mableton property maintenance question to Cobb County is out of date, and Cobb's tenant housing-complaint process was never available here anyway: the county limits it to rental property in unincorporated Cobb.`,
    `Dispossessory jurisdiction did not move. A Mableton eviction is still heard by the Cobb County Magistrate Court at 32 Waddell Street in Marietta, with a seven-day answer period and Tuesday hearings, and Cobb's off-duty peace officer route remains available if the Sheriff cannot execute the writ within 14 days of scheduling. Code enforcement is municipal now; the court is not.`,
  ],
  'tenant-placement:mableton': [
    `A leasing-only owner in Mableton needs one fact more than any market statistic: the city took over code enforcement. Cobb County announced that starting March 3, 2025, the City of Mableton assumed all zoning and code enforcement services within its city limits. Mableton's charter also covers business licensing, building permits, inspections, and zoning and planning, while police, fire, roads and schools stay with Cobb. If you self-manage after placement, the number your tenant calls about a property-maintenance issue is a Mableton number, not a Cobb County one.`,
    `That matters because Cobb's tenant housing-complaint process is limited to rental property in unincorporated Cobb, so it does not cover this address and never will. Whatever standard your property is held to is a city standard, and it is worth knowing which department you are dealing with before the first complaint rather than after it.`,
    `On the leasing side, Mableton is the largest city in Cobb County by its own account — a population of nearly 80,000 — which gives it real depth of applicant pool and real variety of competing inventory. We price against what has actually leased within that submarket rather than against Cobb-wide averages, because a city of this size contains several distinct rental markets and the county number describes none of them.`,
  ],
  'long-term-rental-management:acworth': [
    `A dispossessory on an Acworth address is heard by the Cobb County Magistrate Court at 32 Waddell Street in Marietta, where dispossessory hearings run on Tuesdays at 9 a.m. and 1:30 p.m. and the tenant has seven days from service to file an answer. Cobb states the prerequisites plainly: the relationship must be landlord and tenant, and the landlord must have made a demand for possession of the premises before proceedings commence. That demand — dated, delivered, evidenced — is the single most common gap in a self-managed file.`,
    `Cobb also publishes something most counties do not. Under its off-duty eviction programme, if the Sheriff's Office cannot execute the writ within 14 days of it being scheduled, the landlord may apply to have certified off-duty peace officers execute it instead — the application must be submitted in person at 185 Roswell Street in Marietta at least five days before the intended execution, and the execution is at the landlord's own cost. It is a genuine release valve on a stalled writ, and almost nobody self-managing knows it exists.`,
    `Because Acworth is an incorporated city, Cobb County's tenant housing-complaint process — limited by the county to rental property within unincorporated Cobb — does not apply here. With O.C.G.A. § 36-74-30(b) also barring any Georgia local government from requiring rental registration or inspecting without probable cause, scheduled photo inspections are the only condition record your property will have.`,
  ],
  'tenant-placement:acworth': [
    `Acworth leases to households, not to singles, and that should shape the entire placement. The draw is the lake-and-downtown character at the top of Cobb combined with a straightforward run down I-75, which attracts families willing to trade commute minutes for space. Families sign longer, renew more often, and care about bedroom count, yard and school zone far more than about a renovated kitchen — so the rent-ready punch list should follow that, not a generic renovation list.`,
    `Chattahoochee Technical College's North Metro Campus at 5198 Ross Rd is in the city, and adds a steady thread of staff and student-family demand that runs year-round rather than seasonally.`,
    `Two things to settle at signing, because Acworth is an incorporated city and no county programme will do them for you. Cobb County's tenant housing-complaint process is limited to unincorporated Cobb, and O.C.G.A. § 36-74-30(b) prevents any Georgia local government from requiring rental registration or inspecting without probable cause. That makes the signed, photographed existing-damage list completed before the deposit is accepted the only independent record of the property's condition — and on a self-managed rental it is the document that settles a deposit argument a year later.`,
  ],

  // ==========================================================================
  // PAULDING COUNTY
  // ==========================================================================
  'long-term-rental-management:hiram': [
    `Hiram carries more weight in Paulding County than its size suggests. The county's own plan notes it is one of only three incorporated cities in Paulding, alongside the county seat at Dallas and Braswell, with eight small unincorporated communities besides. And Wellstar Paulding Medical Center is in Hiram — 2518 Jimmy Lee Smith Parkway — not in Dallas, which is where most people assume the county hospital sits. A hospital inside the city limits is the strongest twelve-month rental demand driver Paulding has.`,
    `It matters because the county otherwise commutes away. Paulding County's plan describes it in its own words as "known as a bedroom community, with over 70% of its workers commuting out each day." A rental here is competing for two very different tenants: the commuting household that wants space and a manageable drive, and the hospital household that wants to be five minutes from the door. They value the property differently, and pricing for the wrong one is how a Hiram vacancy stretches.`,
    `Paulding publishes its dispossessory numbers, which is a courtesy Cobb does not extend. The filing fee for service on one defendant is $77, with $25 for each additional defendant served. The tenant has seven days from service to file an answer in the Magistrate Court Clerk's office, and when that seventh day lands on a weekend or a legal holiday the answer may be filed by close of the next business day — a detail that has cost more than one landlord an easy default.`,
  ],

  // ==========================================================================
  // DOUGLAS COUNTY
  // ==========================================================================
  'long-term-rental-management:douglasville': [
    `Douglas County spells out the eviction step that surprises owners, and it is worth reading before you need it. Roughly two working days after judgment, the Sheriff's Office receives the writ of possession — but it is then your responsibility to phone the Warrant/Civil Division to book the appointment, and if you have not called after 30 days the writ is considered inactive. Once a date is set, the defendant gets written notice at least 24 hours ahead, a $25.00 non-refundable fee is due at the time of scheduling, and the county states directly: "You are required to have adequate labor at the location to expedite the removal of property."`,
    `That labor line is the whole difference between a court win and actual possession. The Magistrate Court of Douglas County sits at 8700 Hospital Drive in Douglasville and the Sheriff's Office at 8470 Earl D. Lee Boulevard, so both ends of the process are local — but neither will move a sofa for you.`,
    `The demand side is unusually well documented too. Douglas County's adopted plan lists its top employers as the Douglas County School System, Silver Line Windows and Doors, Wellstar Douglas Medical Center, McMaster-Carr, Google, Medline Industries, Gordon Food Service, Douglas County Government, the American Red Cross and ResMed — and notes those employers are clustered in the Douglasville and Riverside Parkway Business Park areas. Wellstar Douglas Medical Center is at 8954 Hospital Drive. That is a distribution-and-healthcare payroll base, which produces exactly the shift-working, locally-employed renter a twelve-month lease is built around.`,
  ],
  'tenant-placement:douglasville': [
    `Douglasville has been shifting toward renting, and the county's own adopted plan says so with numbers: renter-occupied housing rose from 27% of occupied units in 2010 to 33% in 2020, while median monthly rent moved from $949 to $1,143 between 2016 and 2020 and median home value rose 46% over the same period. The plan goes further, noting concern that more renting among occupants of single-family homes "may be affecting the ability of families to purchase homes" and suggesting demand for more rental product. Placing a tenant into a market moving that way rewards evidence-based pricing and punishes guesswork.`,
    `The applicant pool is payroll-anchored. The county's plan lists the Douglas County School System, Silver Line Windows and Doors, Wellstar Douglas Medical Center, McMaster-Carr, Google, Medline Industries, Gordon Food Service, county government, the American Red Cross and ResMed among its largest employers, clustered around Douglasville and the Riverside Parkway Business Park. Those are verifiable-income households on regular schedules — good screening subjects, and reachable through the MLS as well as the portals.`,
    `One thing to hand over with the keys. Douglas County requires the landlord to have "adequate labor at the location" to remove property at an eviction, charges $25.00 non-refundable at scheduling, and treats a writ as inactive if you have not called within 30 days. A self-managing owner should know that before there is a problem, not during one.`,
  ],
  'long-term-rental-management:lithia-springs': [
    `The first thing to establish about a Lithia Springs rental is that it is almost certainly not in a city. Lithia Springs is an unincorporated community in Douglas County, which means county rules apply directly with no municipal layer in between. Douglas County states that all properties in unincorporated Douglas County must comply with the Douglas County Unified Development Code, the county Code of Ordinances, and the International Property Maintenance Code — and enforcement is request-driven through the county's service centre rather than proactive. There is no rental registration; O.C.G.A. § 36-74-30(b) forbids one anywhere in Georgia.`,
    `The IPMC point is the substantive one. In an incorporated city, property maintenance standards vary with the municipality. Here they are the county's, applied county-wide, and they are the standard a complaint will be measured against — which makes a documented, photographed inspection schedule the cheapest form of insurance an owner can buy.`,
    `Lithia Springs' rental demand comes from the corridors rather than a downtown. The county's own small area plan describes a built environment mixing warehouse, single-family and multifamily, with light industrial and warehouse buildings dating from the 1980s, and names Thornton Road, Veterans Memorial Highway, Sweetwater Road and Sweetwater Industrial Boulevard as its spines. Google has run a data centre in Douglas County since 2003. That industrial base, plus a location the county describes as remarkable for its access to I-20, Cobb County and the City of Atlanta, is what fills these houses on twelve-month leases.`,
  ],

  // ==========================================================================
  // FULTON COUNTY
  // ==========================================================================
  'long-term-rental-management:atlanta': [
    `The Fulton County Marshal's Department publishes the single most under-appreciated fact in Atlanta landlording: the landlord supplies the labor. Its eviction guidance has the landlord either hire an eviction company or arrange another source of labor, and states that five or more able-bodied people are usually required to perfect an eviction efficiently. A deputy marshal calls to schedule the date, writs are handled in the order received, the eviction deputies make the initial entry — you cannot go in first — and the job ends with a walk-through confirming the tenant's property is actually out. Service costs are published too: $35 for a proceeding against a tenant holding over, $25 for a writ of possession, no personal checks, and exact cash if you pay in person.`,
    `Filing is electronic, not optional. Fulton's Magistrate Court requires parties to e-file into the court's case management system; there are free public terminals at the clerk's office in Suite TG-100 of the Justice Center Tower, and a fee if you file anywhere else. The tenant has seven days from service to answer and an eviction may be requested on the eighth day — but once a writ issues, the eviction has to be requested within 30 days or a fresh dispossessory affidavit is required. Owners lose whole months to that clock.`,
    `One structural point for anyone holding property in an LLC. Fulton offers a Rule 31 designation of agent, but Uniform Magistrate Court Rule 31 requires a bona fide officer or full-time employee of the entity that is a party to the action, sworn under penalty of perjury. Whether a third-party manager's staff satisfy that for an owner's LLC is a genuine question, and one worth putting to a Georgia attorney before a hearing date rather than at one.`,
  ],
  'tenant-placement:atlanta': [
    `Before anything else, establish the county. Georgia's dispossessory statute sends the case to a magistrate in the district where the land lies, and Fulton's own landlord guidance makes "the property is located in Fulton County" a precondition of filing there. An Atlanta mailing address does not by itself establish which county the parcel sits in — and the Fulton Marshal's Department states it will not refund its fee if the address turns out to be outside Fulton. That is a placement-stage question, not an eviction-stage one, and we settle it when the lease is drafted.`,
    `The screening standard matters more in Atlanta than almost anywhere in the metro because the applicant pool is so deep and so varied. A written standard, applied identically — verified income against a set threshold, credit, prior landlords telephoned rather than emailed, employment confirmed, public-record review — is simultaneously better filtering and the correct Fair Housing posture when a hundred people can see a listing in a day.`,
    `And the channel is worth paying for. A large share of renters moving into Atlanta for work arrive with an agent attached, because a relocation package pays for one or because it costs them nothing. Those agents search the MLS. A property that lives only on the consumer portals never reaches that pipeline at all, which in a city with this much inbound corporate hiring is a meaningful slice of the households that would have paid your asking rent without negotiating.`,
  ],
  'long-term-rental-management:college-park': [
    `College Park is the rare Georgia city with a codified rental ordinance, and every multi-family owner here needs to read it. Chapter 5, Article V, Division 3 — the Multi-Family Residential Rental Ordinance, as amended by Ordinance 2024-16 — requires owners of multi-family residential property in the city to hold an occupational tax certificate and, before the initial certificate, to supply a code compliance certificate covering 100 percent of the property inspected within the preceding twelve months. Thereafter an annual code compliance certificate must cover at least 20 percent of the units, with every unit inspected at minimum every five years, and exteriors on the same 20-percent-a-year, five-year cycle.`,
    `The 2024 amendment is the part owners get wrong. Routine inspection under subsection (b)(1) "is not required for all multi-family rental properties with nine (9) rental units or less" — but the same subsection preserves a tenant's right "to request an inspection in writing prior to occupying the rental unit, even if the applicable rental unit is exempt," and if requested, the full inspection regime applies at the owner's cost. Since July 1, 2024 the city has also required apartments to hire certified inspectors for their moving inspections. Note the drafting: this hangs on an occupational tax certificate under O.C.G.A. § 48-13-5, not on registration, because O.C.G.A. § 36-74-30(b) forbids any Georgia local government from requiring registration of residential rental property.`,
    `Failure has teeth beyond a fine. The ordinance provides that failure to supply the code compliance certificate shall, upon a judicial determination, be a condition constituting probable cause for inspection by the city building official — at the owner's sole cost, with unpaid costs becoming a lien collected as taxes. Dispossessory jurisdiction stays with Fulton County Magistrate Court, whose South Annex Service Center is at 5600 Stonewall Tell Road here in College Park.`,
  ],
  'tenant-placement:college-park': [
    `A College Park placement carries an obligation most owners have never heard of. Under the city's Multi-Family Residential Rental Ordinance, an inspection is required before any rental unit is occupied by a new tenant, or every five years of an existing tenancy — and while Ordinance 2024-16 exempts multi-family properties of nine rental units or less from that routine inspection, it expressly preserves every tenant's right to request an inspection in writing before occupying the unit, at the owner's cost. If the unit fails, the owner must bring it up to code. That is a rent-ready standard set by ordinance, not by taste, and it is cheaper to meet before the listing goes live.`,
    `The location does the marketing. MARTA's College Park Station sits in the city with 2,056 parking spaces, the Airport station is on the same line, and the Georgia International Convention Center at 2000 Convention Center Concourse describes itself as Georgia's second largest convention center, two minutes from Hartsfield-Jackson. Airport-adjacent shift work and rail access are what an applicant here is actually buying, and the listing should say so plainly.`,
    `One boundary note: the ordinance above applies to multi-family property. A single-family rental in College Park is not covered by it, and no Georgia local government may require you to register a residential rental in any case — O.C.G.A. § 36-74-30(b) forbids it. We confirm which regime your specific property falls under before we quote a rent, because the compliance cost differs and it belongs in the number.`,
  ],
  'long-term-rental-management:east-point': [
    `A useful thing to know about East Point before you need it: the city's Municipal Court at 2727 East Point Street handles traffic citations, school-zone camera violations and city ordinance violations — it does not hear evictions. Georgia limits municipal courts to ordinance matters, and gives magistrate courts jurisdiction over dispossessory proceedings, so an East Point eviction is filed with the Fulton County Magistrate Court downtown and executed by the Fulton County Marshal's Department. Owners who assume the local courthouse handles their tenant lose time discovering otherwise.`,
    `The Marshal's requirements are where the real planning happens. Its published eviction guidance has the landlord hire an eviction company or arrange another source of labor, notes that five or more able-bodied people are usually required, and reserves the initial entry to the eviction deputies. A deputy marshal schedules the date; the day ends with a walk-through confirming the property is out.`,
    `East Point's own code enforcement sits under the Police Department rather than under planning, which changes who you are dealing with when a complaint is raised. And because O.C.G.A. § 36-74-30(b) bars any Georgia local government from requiring registration of residential rental property or inspecting without probable cause of a violation, nothing proactively checks your house. MARTA's East Point Station, with 1,002 parking spaces, anchors the commuter demand that fills these properties on twelve-month leases.`,
  ],
  'tenant-placement:east-point': [
    `East Point's leasing pitch is rail, and it is a real one. MARTA's East Point Station is in the city with 1,002 parking spaces, which puts a renter on the same line as the airport and downtown without a car payment. That reaches a specific applicant — airport and hospitality shift workers, downtown employees who would rather not drive the Connector — and it is worth putting at the top of the listing rather than burying it under a feature list.`,
    `Price against what has actually leased nearby, not against intown Atlanta. East Point's stock and its rents are their own market, and the most common cause of a long vacancy here is an owner benchmarking against a neighbourhood on the other side of the airport.`,
    `Two administrative facts to hand over with the keys. East Point's code enforcement sits under the Police Department, not planning — so a complaint routes differently than owners expect. And the city's Municipal Court does not hear evictions; a dispossessory goes to Fulton County Magistrate Court and is executed by the Fulton County Marshal, whose guidance requires the landlord to supply the labor, with five or more able-bodied people usually needed. Self-managing owners should know that on day one, not on the day it matters.`,
  ],
  'long-term-rental-management:fairburn': [
    `Fairburn commissioned an actual housing study, which is unusual for a city this size and genuinely useful to an owner. The Citywide Housing Market Analysis prepared by Noell Consulting Group, dated August 2024, records Fairburn as a 17-square-mile city whose population growth ran 7.7% annually from 2000 to 2010 before slowing to 1.8% annually from 2010 to 2023 — still near the top of the ten-county Atlanta core. Population density rose from 761 per square mile in 2012 to 974 in 2022, a 28% increase, ahead of Peachtree City, Fayetteville and Newnan over the same period.`,
    `The study attributes that density to new multifamily inside the city boundaries, naming The Dylan and Oslo specifically, alongside new construction by builders including Liberty Homes, Lennar and D.R. Horton in the surrounding area. For a long-term rental owner that is the competitive set in one sentence: your house is being viewed by people who also toured a new garden apartment and a new-build subdivision the same weekend. Condition and photography carry more weight here than in a market with no new supply.`,
    `On process, two things are fixed. There is no MARTA rail station in Fairburn — the network's southern rail terminates at Airport and College Park — so this is a car-dependent submarket and parking and drive times matter to applicants. And a dispossessory is heard by the Fulton County Magistrate Court and executed by the Fulton County Marshal, whose guidance requires the landlord to arrange labor, usually five or more able-bodied people, with the deputies making the initial entry.`,
  ],
  'tenant-placement:fairburn': [
    `Fairburn is competing against new construction, and its own housing study says so. The Citywide Housing Market Analysis by Noell Consulting Group, dated August 2024, credits the city's density increase — 761 people per square mile in 2012 to 974 in 2022, up 28% — to new multifamily inside the city boundaries, naming The Dylan and Oslo, plus new homes from Liberty Homes, Lennar and D.R. Horton nearby. An applicant walking through your house has very likely toured one of those the same week.`,
    `That sets the rent-ready standard rather than the rent. You do not have to beat a 2024 apartment on finishes; you have to be clean, photographed properly, and priced against what comparable houses have actually leased for. Where owners lose six weeks in Fairburn is by pricing to the new-build asking rents while presenting a property that has not been touched since the last tenant.`,
    `Two practical notes for the listing. There is no MARTA rail station in Fairburn — the rail network's southern end is at College Park and Airport — so commuting applicants are driving, and I-85 access and parking belong in the copy. And because a large share of relocating renters in this part of the metro come through an agent, the property belongs on the MLS as well as the consumer portals; the agent channel is the one an owner-listed rental never reaches.`,
  ],
  'long-term-rental-management:hapeville': [
    `Hapeville is one of the clearest cases in the metro where the twelve-month lease is not a fallback but the main road. The city's short-term rental permit requires the applicant to be a Hapeville resident and to hold a current Fulton County Homestead Exemption, with fees of $250 for a primary dwelling and $1,000 for a second short-term rental dwelling, on a January-to-December permit renewed by 31 December. A homestead-exemption condition is, in practice, a residency test — which effectively closes the short-term route to a non-resident investor and makes long-term leasing the workable strategy for that owner.`,
    `The rest is Fulton County procedure. There is no MARTA rail station in Hapeville, so a renter here is driving or riding a bus, and proximity to the airport rather than to a platform is what fills the property. A dispossessory is heard by the Fulton County Magistrate Court, which requires electronic filing, gives the tenant seven days from service to answer, and permits an eviction to be requested on the eighth day — after which the eviction must be requested within 30 days of the writ or a new affidavit is needed.`,
    `The Fulton County Marshal executes the writ from 160 Pryor Street SW, and its published guidance puts the labor on the landlord: hire an eviction company or arrange another source, with five or more able-bodied people usually required, and the eviction deputies making the initial entry. Its fee schedule lists $35 for a proceeding against a tenant holding over and $25 for a writ of possession, with no personal checks accepted.`,
  ],

  // ==========================================================================
  // GWINNETT COUNTY
  // ==========================================================================
  'long-term-rental-management:lawrenceville': [
    `Lawrenceville is where Gwinnett's eviction machinery physically lives, and the numbers are published. The Magistrate Court's Civil Division is at 75 Langley Drive; a dispossessory costs $60.00 to file plus $25.00 sheriff service per defendant — $85.00 for one tenant — with a further $25.00 to serve the writ of possession, and eFiling through eFileGA runs $14 per case per party. The tenant has seven days from service to answer, and dispossessory calendars are usually heard on Wednesdays at 9:00 a.m. or 1:00 p.m.`,
    `The Sheriff's side is where owners get caught out. You must bring the writ to the Civil Processing Office within 30 days of issuance or it goes back to the Clerk of Court, the $25 fee is fixed by O.C.G.A. § 15-16-21(b)(12), and the office states plainly that deputies do not assist in the physical removal of property. Its requirement is a labor force of at least two people per bedroom for a residential eviction, sized so the job finishes inside two hours. On a four-bedroom that is eight people you are hiring.`,
    `Lawrenceville is also the one city here with a renter majority — Gwinnett's own Comprehensive Housing Study, using 2019 American Community Survey data, put the city at 49% owner-occupied against 51% renter-occupied, and identified Lawrenceville alongside the I-85 and I-985 corridors as where the county's rental housing concentrates. Georgia Gwinnett College at 1000 University Center Lane, with 12,782 students in fall 2025 and only 1,029 private rooms on campus, plus Gwinnett Technical College on Sugarloaf Parkway, keep that demand renewing.`,
  ],
  'tenant-placement:lawrenceville': [
    `Lawrenceville is a renter-majority city, which changes the whole placement calculation. Gwinnett County's own Comprehensive Housing Study, drawing on 2019 American Community Survey data, put the city at 51% renter-occupied against 49% owner-occupied — the only one of Gwinnett's larger cities where renters outnumber owners — and identified Lawrenceville, along with the I-85 and I-985 corridors, as where the county's rental housing concentrates. Deep supply means an overpriced listing is not merely slow; it is invisible.`,
    `The demand under it is institutional. Georgia Gwinnett College at 1000 University Center Lane enrolled 12,782 students in fall 2025 and houses only 1,029 private rooms on campus, which pushes the balance into the surrounding rental market every August. Gwinnett Technical College's main campus on Sugarloaf Parkway and the county government complex at 75 Langley Drive add year-round staff demand that is not tied to the academic calendar at all — and those are the applicants worth writing the listing for if you want a tenancy that renews.`,
    `Set expectations on cost before you self-manage. A dispossessory here runs $60.00 to file plus $25.00 sheriff service per defendant and $25.00 to serve the writ, and the Gwinnett Sheriff requires the landlord to supply a labor force of at least two people per bedroom because deputies do not assist in the physical removal of property. Knowing that at signing is what makes a rigorous screening standard feel cheap.`,
  ],
  'long-term-rental-management:lilburn': [
    `Lilburn has done something most Georgia cities have not: it adopted its own property maintenance standards into the City Code, based on the International Property Maintenance Code and enforceable inside the city limits, and it puts code enforcement officers inside the Lilburn Police Department rather than in a planning office. Enforcement runs complaint to inspection to written notice with a correction date, then a citation and a Municipal Court appearance if the property does not come into compliance.`,
    `The city also requires registration of vacant or foreclosed property: owners of properties uninhabited for 60 days or partially constructed must register with the city or be subject to a fine, with the form going to Code Enforcement at 340 Main Street and a boarding-up permit sometimes required. That distinction is worth being precise about, because O.C.G.A. § 36-74-30(b) provides that in no event may a local government require the registration of residential rental property. A vacancy registry is not a rental registry — but a rental that sits empty between tenancies for two months can walk into one.`,
    `The county's own interior-code programme stops at the city line. Gwinnett adopted the IPMC's interior standards for rentals effective 31 July 2023 and states that it inspects properties within unincorporated Gwinnett County and does not address code violations within city limits. So a Lilburn tenant's route is the city's police-based code enforcement, not the county's. A dispossessory still goes to the Gwinnett Magistrate Court at 75 Langley Drive in Lawrenceville.`,
  ],
  'tenant-placement:lilburn': [
    `Lilburn's rental stock is overwhelmingly houses, which shapes both the pricing and the pool. Gwinnett County's Comprehensive Housing Study describes the city's housing as primarily single-family homes largely built in the last quarter of the twentieth century, with the city now reviewing proposals for townhomes, senior housing and less traditional single-family lots, and identifying higher-density and mixed-use opportunity along the US 29 corridor. Using 2019 American Community Survey data, the same study put Lilburn at 62% owner-occupied and 38% renter-occupied.`,
    `A late-twentieth-century house competing against newer product elsewhere in Gwinnett wins on space and school zone, not on finishes. The rent-ready punch list should follow that: paint, floors, working systems and honest photography move this market; a speculative kitchen usually does not.`,
    `One thing to flag to a self-managing owner at handover. Lilburn has adopted its own IPMC-based property maintenance standards into the City Code and runs code enforcement out of the Police Department, and it requires vacant or foreclosed properties — those uninhabited for 60 days or partially constructed — to be registered with the city or face a fine. A long gap between tenancies is not just lost rent here; it can create a filing obligation. That is a real argument for not leaving a Lilburn property sitting while you hold out for an optimistic number.`,
  ],
  'long-term-rental-management:norcross': [
    `Norcross sits at Gwinnett's gateway from DeKalb along I-85, and the county's own housing study treats it as one of the municipalities with a higher renter share — 50% owner-occupied and 50% renter-occupied on 2019 American Community Survey data, effectively an even split. The county's planning work describes the Jimmy Carter Boulevard corridor as multi-cultural and targets its transition from an auto-oriented strip to a mixed-use corridor, with workforce-housing incentives inside the Jimmy Carter Boulevard Overlay and accessory dwelling units among the tools contemplated.`,
    `The regulatory line that matters is the city limit. Gwinnett County adopted the International Property Maintenance Code's interior standards for residential rentals effective 31 July 2023 — and states that it inspects properties within unincorporated Gwinnett County and does not address code violations within city limits. A tenant inside Norcross cannot use the county's interior-inspection route; the city's own code enforcement applies instead. Any advice pointing a Norcross tenant at the county's code enforcement line is simply wrong.`,
    `A dispossessory is filed with the Gwinnett Magistrate Court at 75 Langley Drive in Lawrenceville — $60.00 filing plus $25.00 sheriff service per defendant, $25.00 to serve the writ — with a seven-day answer period and calendars usually heard on Wednesdays. The Sheriff requires the landlord to field at least two people per bedroom, because deputies do not assist in the physical removal of property.`,
  ],
  'tenant-placement:norcross': [
    `Norcross is roughly an even split between owners and renters — Gwinnett County's Comprehensive Housing Study, on 2019 American Community Survey data, puts it at 50% owner-occupied and 50% renter-occupied — and the county groups it with the municipalities carrying a higher renter share. The study also credits new mixed-use and townhome development around the historic downtown with broadening the city's housing choices, which is the inventory a house here is now shown against.`,
    `The applicant pool is genuinely multilingual, and the city's own practice acknowledges it: Norcross maintains a Spanish-language section of its website, and the county's planning work describes the Jimmy Carter Boulevard corridor as multi-cultural. Gwinnett County Public Schools reports students from 183 countries speaking 114 languages. Screening has to be rigorous and identical for every applicant here — a written standard, applied the same way regardless of who is asking, is both better filtering and the correct Fair Housing posture in a market this diverse.`,
    `One boundary fact worth handing over. Gwinnett County's tenant-facing interior code inspection applies only in unincorporated Gwinnett — the county says it does not address code violations within city limits — so a Norcross tenant's route runs through the city, not the county line an owner might have been given elsewhere.`,
  ],
  'long-term-rental-management:duluth': [
    `Duluth carries a genuinely different renter profile from the rest of Gwinnett, and the city publishes the evidence. Its economic development page, citing 2022 American Community Survey five-year estimates, reports that nearly 30% of Duluth's residents were born outside the United States — 61.6% of those from Asia and 23.7% from Latin America — with a median household income of $88,915 and 53.0% of residents holding a bachelor's degree or higher against 38.9% countywide. Gwinnett County's Comprehensive Housing Study, on 2019 data, put the city at 55% owner-occupied and 45% renter-occupied.`,
    `Employment is close at hand rather than downtown. AGCO's Global and North America headquarters is at 4205 River Green Parkway in Duluth, and the Gas South District at 6400 Sugarloaf Parkway — arena, convention center, theater and the Hudgens Center for Art and Learning — anchors an events and hospitality workforce. The county's housing study also notes Duluth's stated interest in executive-style housing along Peachtree Industrial Boulevard, on the view that the city has multifamily and starter product but a shortage at the upper end.`,
    `On enforcement, know the city line. Gwinnett County's interior property-maintenance code for rentals, effective 31 July 2023, applies only in unincorporated Gwinnett — the county says it does not address code violations within city limits. Duluth enforces its own property maintenance ordinance instead, beginning with a written notice of violation allowing no more than thirty days before a Municipal Court citation. A dispossessory still goes to the Gwinnett Magistrate Court at 75 Langley Drive.`,
  ],
  'tenant-placement:duluth': [
    `Duluth's applicant pool is the most internationally weighted in our Gwinnett coverage, and the city says so in its own numbers: citing 2022 American Community Survey five-year estimates, it reports that nearly 30% of residents were born outside the United States, 61.6% of them from Asia and 23.7% from Latin America, with 53.0% of residents holding a bachelor's degree or higher against 38.9% countywide and a median household income of $88,915. Duluth's own website runs in Korean, Chinese, Vietnamese and Spanish alongside English.`,
    `That has practical consequences for a placement. Employment and prior-landlord verification often reach overseas or non-English-speaking references, and an applicant with thin US credit history may still be an excellent tenant — which is exactly why the screening standard has to be written down before the listing goes live and then applied identically. Criteria that flex applicant by applicant are how Fair Housing complaints start, and in this market they also cost you good tenants.`,
    `On competing inventory, the county's Comprehensive Housing Study put Duluth at 55% owner-occupied and 45% renter-occupied on 2019 data, and records the city's own view that it has multifamily and starter housing but a shortage of upper-end product, with executive-style housing targeted along Peachtree Industrial Boulevard. A well-presented larger home therefore competes in a thinner field here than the raw rental share suggests. AGCO's Global and North America headquarters at 4205 River Green Parkway and the Gas South District on Sugarloaf Parkway are the demand anchors worth naming in the listing.`,
  ],
  'long-term-rental-management:grayson': [
    `Grayson is the most owner-occupied market we manage in, and that single fact should shape every expectation an owner brings to it. Gwinnett County's Comprehensive Housing Study, on 2019 American Community Survey data, recorded 1,617 owner-occupied households against 76 renter-occupied — about 96% owner-occupied — with a median household income of $111,528, second highest in the county. A rental here is a genuine rarity on its street, not one of a hundred similar units.`,
    `The city intends to keep it that way. Grayson's adopted comprehensive plan states as housing policy that freestanding apartments are discouraged, on the reasoning that there are numerous apartment complexes around Grayson in the county, and it commits to enforcing property maintenance ordinances and adding code enforcement capacity to address complaints and promote neighbourhood upkeep. The plan also notes the city has only around 182 acres of vacant residential land left, translating to roughly 455 additional single-family lots.`,
    `Two operating consequences follow. Your comparable set is small and mostly other single-family houses, so pricing has to come from what actually leased rather than from a county average. And in a neighbourhood of owner-occupiers, a poorly maintained rental is conspicuous — which is precisely the property a complaint-driven code enforcement programme finds. Scheduled, photographed inspections are cheaper than being the house the street complains about. A dispossessory goes to the Gwinnett Magistrate Court at 75 Langley Drive in Lawrenceville.`,
  ],
  'long-term-rental-management:dacula': [
    `Dacula is an owner's market with a thin rental layer, and the numbers matter for pricing. Gwinnett County's Comprehensive Housing Study, using 2019 American Community Survey data, recorded 1,547 owner-occupied households against 541 renter-occupied — roughly 74% owner-occupied — with a median household income of $80,192. The study describes Dacula as sitting in eastern Gwinnett along Highway 29 and experiencing an increase in residential subdivision development, with the city's own goals aimed at infill housing and eliminating substandard housing.`,
    `That combination — new subdivisions, few rentals — means your competitive set is small and mostly new. A twenty-year-old house priced off a countywide average will sit; the same house priced off what comparable Dacula homes actually leased for, and presented properly, does not.`,
    `The regulatory picture is a two-layer one and the city limit decides it. Gwinnett County adopted the International Property Maintenance Code's interior standards for residential rentals effective 31 July 2023 and lets tenants request an interior inspection — but the county states it inspects properties within unincorporated Gwinnett County and does not address code violations within city limits. Much of what carries a Dacula mailing address is unincorporated, so which regime applies turns on the parcel, not the postmark. We confirm that per address. A dispossessory goes to the Gwinnett Magistrate Court at 75 Langley Drive in Lawrenceville, where the tenant has seven days to answer and calendars are usually heard on Wednesdays.`,
  ],

  // ==========================================================================
  // DEKALB COUNTY
  // ==========================================================================
  'long-term-rental-management:decatur': [
    `Being the county seat has one very practical benefit for a Decatur landlord: the court is here. A dispossessory is filed with the DeKalb County Magistrate Court in the Administration Tower at 556 N. McDonough Street, Room 200, and the court publishes the numbers — $104.00 to file a dispossessory warrant, with the Marshal serving it at $50.00 for each named defendant. At the writ stage there is a $13 application fee plus a $75 Marshal service fee. Naming every adult occupant on the lease is therefore not just good practice here; it is a line item.`,
    `The DeKalb County Marshal's requirements are where owners underestimate the day itself. Its published eviction procedure requires the landlord to provide sufficient labor to safely remove all items — usually a minimum of five workers — and to provide a way to gain entry, such as a pass key or a locksmith. Allow two business days for the writ to reach the Marshal's office, then schedule within 30 days of issuance. The deputy performs a safety sweep and authorises your crew to begin; your crew carries everything to the nearest right-of-way, and debris removal stays your responsibility afterwards.`,
    `One boundary point worth knowing. DeKalb County's multifamily Code Compliance Certificate programme applies only to owners of four or more units within the unincorporated parts of the county, so a rental inside the City of Decatur sits outside it. We have not found a comparable multifamily rental inspection programme in Decatur's own city code — which means, in practice, that the condition record on your property is the one your manager creates and nobody else's.`,
  ],
  'tenant-placement:decatur': [
    `Decatur's rental market is small, tightly held and priced by school attendance zone more than by square footage — City Schools of Decatur is a separate district from DeKalb County's, and a family relocating here usually knows exactly which side of the line they need before they call. Getting that right in the listing is the difference between a fast lease at the top of the band and six weeks of viewings by people who were never going to sign.`,
    `The applicant pool skews toward households who want a twelve-month lease near work rather than near nightlife: hospital and campus staff, county employees at the courthouse complex on North McDonough Street, and professionals who want to keep one car. Those applicants verify well and renew well, and they respond to a listing that leads with commute and schools rather than with finishes.`,
    `A placement-stage note on cost, so a self-managing owner is not surprised later. A dispossessory in DeKalb costs $104.00 to file with $50.00 Marshal service per named defendant, then $13 for the writ application and $75 for the Marshal to serve it — and the Marshal requires the landlord to supply the labor, usually a minimum of five workers, plus a pass key or locksmith for entry. Every one of those costs scales with how sloppy the lease was. We name every adult occupant and document the move-in condition precisely for that reason.`,
  ],
  'long-term-rental-management:brookhaven': [
    `Brookhaven runs its own apartment inspection regime, and it is stricter than the county's. The city requires each apartment community to perform internal inspections on one-half of its units annually, omitting units inspected in the prior two years and noting them in the inspection log, so the rotation actually reaches the whole property. Reports must reach the city no later than 31 December before the following year's Occupational Tax Certificate can be issued, and property managers must use inspectors the City of Brookhaven has approved — your usual contractor will not do.`,
    `That is a different animal from DeKalb County's programme, which applies to owners of four or more units within the unincorporated parts of the county on a 100%-then-20%-a-year, five-year cycle. Because Brookhaven is incorporated, the county programme does not reach it and the city's does. Owners running a portfolio across the county line are complying with two different rulebooks on two different calendars, and the December deadline is the one that quietly catches people.`,
    `Dispossessory jurisdiction stays with the county. A Brookhaven eviction is filed at the DeKalb County Magistrate Court, 556 N. McDonough Street, Room 200 in Decatur — $104.00 to file, $50.00 Marshal service per named defendant, then $13 for the writ application and $75 for service. The DeKalb Marshal requires the landlord to provide sufficient labor, usually a minimum of five workers, and a way to gain entry such as a pass key or a locksmith.`,
  ],
  'tenant-placement:brookhaven': [
    `If you own an apartment community in Brookhaven, placement and compliance are on the same calendar. The city requires each community to internally inspect half its units annually, skipping units done in the prior two years, with reports submitted no later than 31 December before the next Occupational Tax Certificate can issue — and the inspectors must be ones the city has approved. Turning a unit for a new tenant is the cheapest moment to satisfy that, and the most expensive moment to discover you have not.`,
    `For a single-family or small rental, the calculus is different: Brookhaven's apartment programme is aimed at apartment communities, and DeKalb County's four-or-more-unit Code Compliance Certificate programme applies only in the unincorporated parts of the county, so it does not reach a Brookhaven address either. That leaves the move-in condition record as the only independent documentation of the property — signed, photographed, and completed before the deposit is accepted.`,
    `On the leasing itself, the applicant pool here is professional and agent-attached. A meaningful share of renters relocating into this part of the perimeter are working with an agent, and agents search the MLS. A Brookhaven rental listed only on the consumer portals is invisible to that channel — which is the one most likely to bring a tenant who signs at the asking rent.`,
  ],
  'long-term-rental-management:chamblee': [
    `Chamblee is the only city in our DeKalb coverage running two separate programmes at a rental, and owners regularly conflate them. The codified one is the Multifamily Inspection Program: owners of properties receiving income from five or more multifamily rental units must submit inspection reports covering 25% of units each year, completing every unit over four years, at occupational tax certificate renewal or no later than 30 April. Newly constructed properties get a four-year grace period after the certificate of occupancy. Submissions include the code compliance certificate, the inspector's own business licence, a liability insurance certificate, a unit inspection list showing current and prior inspections, and a checklist for every unit inspected.`,
    `The second is the Apartment Code Enforcement Sweeps Program, and it is not the same thing at all. The city's Code Enforcement Division conducts in-depth sweeps of apartment properties, notifying owners and managers by certified mail in advance, inspecting on weekdays between 8 a.m. and 5 p.m. against a standard checklist, then documenting violations with photographs and correction timeframes. Where no progress is made, a formal Notice of Violation is issued. Chamblee describes the intent as educating owners and managers and working with them — but it is a scheduled, proactive sweep, not a complaint response.`,
    `Note what does not apply: DeKalb County's own four-or-more-unit Code Compliance Certificate programme runs only in the unincorporated parts of the county, so it stops at Chamblee's line. Evictions do not — a dispossessory is filed at the DeKalb County Magistrate Court on North McDonough Street in Decatur, and the DeKalb Marshal requires the landlord to supply the labor, usually a minimum of five workers, plus a pass key or locksmith.`,
  ],
  'tenant-placement:chamblee': [
    `A Chamblee placement should be timed against the city's calendar, not just the market's. Owners with five or more multifamily rental units must file inspection reports covering 25% of units each year — all units over four years — at occupational tax certificate renewal or no later than 30 April, using a code compliance certificate, the inspector's business licence, a liability insurance certificate and a per-unit checklist. A unit being turned for a new tenant is already open and empty, which is the cheapest possible moment to get it inspected and documented.`,
    `Separately, the city's Code Enforcement Division runs proactive Apartment Code Enforcement Sweeps: owners and managers are notified by certified mail before an area inspection, staff inspect weekdays between 8 a.m. and 5 p.m. against a checklist, and violations are photographed with correction timeframes. Presenting a property that would pass a sweep is the same standard as presenting one that leases quickly, so the work is not duplicated.`,
    `The applicant pool along this corridor is strongly international, and screening has to be written down before the listing goes live and applied identically to everyone. Applicants with overseas employment history or thin US credit files are common here and are frequently excellent tenants; criteria that flex from one applicant to the next are how Fair Housing exposure starts, and they cost you good tenants at the same time.`,
  ],
  'long-term-rental-management:clarkston': [
    `Clarkston's rental demand has a documented origin that no other city in the metro shares. The city's own history states that beginning in the 1990s, newcomer asylum programmes identified Clarkston as an ideal place to resettle, that today half of the city's residents are foreign born and hail from over 50 countries across six continents, and that the city proudly proclaims itself "the Ellis Island of the South." For a long-term rental that translates into a deep, stable, family-sized renter pool — and into practical requirements most managers never plan for, from multilingual communication to income verification that reaches employers who do not answer email.`,
    `It also means screening has to be genuinely written down and genuinely uniform. A thin domestic credit file is common here and is not the same thing as a weak applicant. A documented standard — verified income against a set threshold, prior landlords telephoned, employment confirmed, public-record review, applied identically to every adult — is both the better filter and the correct Fair Housing posture in a city this diverse.`,
    `On process, the county programme stops at the line: DeKalb's multifamily Code Compliance Certificate requirement covers owners of four or more units within the unincorporated parts of the county, and Clarkston is incorporated. A dispossessory is filed at the DeKalb County Magistrate Court, 556 N. McDonough Street, Room 200 in Decatur — $104.00 to file plus $50.00 Marshal service per named defendant — and the DeKalb Marshal requires the landlord to provide sufficient labor, usually a minimum of five workers, and a way to gain entry such as a pass key or locksmith.`,
  ],
  'tenant-placement:clarkston': [
    `Clarkston places differently from anywhere else we work, and the city says why in its own words: beginning in the 1990s, newcomer asylum programmes identified Clarkston as an ideal place to resettle; today half its residents are foreign born, from over 50 countries across six continents; and the city calls itself "the Ellis Island of the South." The practical consequence for an owner is a deep pool of household applicants who want space and stability rather than a short lease — which is exactly the tenancy a leasing-only engagement should be aiming for.`,
    `It also changes the mechanics of verification. Employment references may be at businesses that do not answer email, prior-landlord history may be short, and domestic credit files are often thin without being weak. That is why the screening standard has to exist on paper before the listing goes live: verified income against a set threshold, prior landlords telephoned directly, employment confirmed, public-record review — applied the same way to every adult applicant, every time. Uniformity is the whole defence and the whole quality control.`,
    `Set the file up properly at signing. A future dispossessory would be filed with the DeKalb County Magistrate Court in Decatur at $104.00 plus $50.00 Marshal service per named defendant, and the Marshal requires the landlord to supply the labor and a means of entry. Every adult occupant named on the lease at the outset is the single cheapest insurance against that day going badly.`,
  ],

  // ── Researched 2026-09-01. Court names, addresses and fees are read off the
  //    courts' own published schedules; Census figures are ACS 2020-2024.
  'long-term-rental-management:alpharetta': [
    `An Alpharetta tenancy is a Fulton County matter the moment anything goes wrong, and Fulton is not a cheap or forgiving venue to learn in. A dispossessory is filed with the Fulton County Magistrate Court at 185 Central Avenue SW in Atlanta, and the cost is not one number: the court's own schedule lists $60.00 for the proceeding against a tenant holding over, $35.00 for Marshal service, $8.00 for each additional named defendant, and a further $75.00 for the writ of possession later in the process. Owners who budget "about seventy-five dollars for an eviction" have read one line of a four-line schedule.`,
    `The city has told owners, in writing, that it intends to hold the rental share down. Alpharetta's 2045 Comprehensive Plan, adopted on 22 June 2026, sets Housing Policy 2 as maintaining "a balance between owner-occupied and renter-occupied in Alpharetta such that at least 68% of the housing stock is owner-occupied," and commits the city to tracking Census data and updating its Rental Housing Study twice a year to watch it. Census figures for 2020-2024 already put owner-occupancy at 65.1% — 8,737 of 25,032 occupied homes are rented — so the policy target sits above where the market currently is. Median gross rent is $1,948. Read together, that is a city actively trying to constrain the supply an owner here is part of, which is a supply argument in the owner's favour and a planning-risk argument against.`,
    `Georgia's timings are tighter than most owners expect and they run against the landlord as often as for them. A tenant has seven days from actual service to answer, orally or in writing, and may raise any defence or counterclaim. In a nonpayment case the tenant can also stop the whole thing by tendering all rent owed plus costs within those seven days — a complete defence the landlord must accept, though only once per tenant in any twelve-month period. If judgment does come, the writ of possession takes effect seven days after it is entered and must be applied for execution within thirty days.`,
    `The deposit rules changed in 2024 and a lot of Alpharetta owners are still working to the old ones. The Safe at Home Act caps a residential security deposit at two months' rent, requires a three-day right to cure before a nonpayment filing, and requires the property to be fit for human habitation. Underneath that, the older law still stands: the deposit sits in an escrow account at a regulated institution, the tenant gets a written condition list before the deposit is tendered, the landlord inspects within three business days of the tenancy ending, and the deposit comes back inside thirty days with a written statement giving the exact reasons for anything withheld. Ordinary wear and tear can never be charged against it. Skip the move-in list and the move-out deduction is close to indefensible.`,
  ],

  'long-term-rental-management:smyrna': [
    `A Smyrna tenancy answers to Cobb County. A dispossessory against a Smyrna tenant is filed with the Cobb County Magistrate Court at 32 Waddell Street in Marietta — not in Atlanta, and not wherever the owner happens to live. Cobb sets its own fee schedule and revises it, so the figure to work from is whatever the clerk quotes on the day rather than a number carried over from a previous filing in another county.`,
    `What does not vary by county is the statutory clock, and it is short. A tenant has seven days from actual service to answer, and may raise any defence or counterclaim in that answer. In a nonpayment case the tenant can defeat the action outright by tendering all rent owed plus costs inside those seven days, which the landlord must accept once per tenant per twelve months. A writ of possession takes effect seven days after judgment and has to be executed within thirty. A file that is not in order before it is filed does not get a second attempt cheaply.`,
    `Smyrna's practical difficulty is turnover rather than law: it is an inside-the-Perimeter market with a large renter base and short move cycles, so the deposit paperwork gets exercised far more often than in a market where tenants stay five years. Georgia's requirements are unforgiving of sloppiness. The deposit is escrowed at a regulated institution, the tenant receives a written condition list before the deposit is tendered, the landlord inspects within three business days of the tenancy ending, and the money is returned within thirty days with a written statement of the exact reasons for any deduction — never for ordinary wear and tear. Since 2024 the deposit itself may not exceed two months' rent.`,
  ],

  'long-term-rental-management:woodstock': [
    `Woodstock is a Cherokee County filing and, unusually, a clean one to quote. The Cherokee County Magistrate Court sits at 90 North Street, Suite 150 in Canton, and the Clerk of Courts publishes the number outright: $86.00 for a petition for writ of dispossessory, including Sheriff's service for one tenant, plus $25.00 for service on each additional tenant. That is a single all-in figure where Fulton itemises across four lines — worth knowing before comparing counties on cost.`,
    `The market is genuinely renter-shaped despite the reputation. Census figures for 2020-2024 put 5,302 of Woodstock's 14,730 occupied homes in the hands of renters — 36% — with a median gross rent of $1,821. The city's own 2023 Comprehensive Plan is blunt about the direction of travel: land and housing "has become unattainable for a small but steadily growing portion of the community," and its five-year work programme commits to creating opportunities for "duplexes, triplexes, cottage courts, bungalows, and other types of missing middle housing." An owner letting a conventional single-family home here is renting into demand the city has said out loud it cannot meet.`,
    `One regulatory point catches Woodstock owners specifically. The city has required a short-term rental certificate and a home occupation licence since 2021, and that regime is enforced — but there is no equivalent registration, inspection or licensing scheme for ordinary long-term rentals. A twelve-month let does not need a city permit; it needs the state paperwork done properly. Deposit escrowed at a regulated institution, written condition list before the deposit is taken, inspection within three business days of the tenancy ending, return within thirty days with the exact reasons for any deduction, and since 2024 a deposit capped at two months' rent.`,
  ],

  'tenant-placement:buford': [
    `Buford has a problem no other city on this list has: it is not in one county. The city spans Gwinnett, Hall and Barrow, so there is no single "Buford court" — a dispossessory has to be filed in the magistrate court of the county the specific parcel sits in. For the Gwinnett portion, which covers most of the city, that is the Gwinnett County Magistrate Court at 75 Langley Drive in Lawrenceville, where the cost is $60.00 to file plus $25.00 sheriff's service per defendant, so $85.00 for a single tenant. Establishing which county an address falls in belongs at the start of a placement, not at the point somebody needs to file.`,
    `Placement-only work stops where management begins: the property is marketed, shown, screened and let on a properly executed Georgia lease, then the keys go to the owner. That makes the paperwork the entire deliverable, because the owner will be the one living with it. The screening standard has to exist in writing before the listing goes live — verified income against a set threshold, prior landlords telephoned rather than emailed, employment confirmed, public-record review — and be applied identically to every adult applicant. Uniformity is simultaneously the fair-housing defence and the quality control.`,
    `Two things must be right at signature or they cannot be fixed later. Every adult occupant is named on the lease, because a dispossessory can only remove people the filing names. And the deposit is handled to the letter: escrowed at a regulated institution, a written condition list given to the tenant before the deposit is tendered, and — since the Safe at Home Act in 2024 — capped at two months' rent. An owner self-managing after placement inherits the thirty-day return deadline and the written-reasons requirement, so we set the file up expecting them to use it.`,
  ],

  'tenant-placement:snellville': [
    `A Snellville placement is a Gwinnett County file. Any future dispossessory goes to the Gwinnett County Magistrate Court at 75 Langley Drive in Lawrenceville, at $60.00 to file plus $25.00 sheriff's service per named defendant — $85.00 for one tenant, and more for each additional adult on the lease. That last detail matters more in a placement than in full management, because the owner who takes the keys back is the one who will pay it.`,
    `Snellville is an unusually owner-occupied market, and that changes what a placement competes against. Census figures for 2020-2024 put 5,586 of 7,135 occupied homes in owners' hands — 78.3% — against 67% for Gwinnett County as a whole, with a median gross rent of $1,818. The city's own 2045 Comprehensive Plan makes the same point and treats it as a problem to solve: detached single-family homes are "94 percent of all housing units," and "increasing housing options to include townhomes and multifamily can help provide in-demand housing and strike a good rental-occupancy balance." Snellville has gone as far as writing build-to-rent duplex zoning into its development ordinance. For an owner that means thin comparable supply and a less transient applicant pool than anywhere inside the Perimeter — pricing to a metro average tends to be wrong here in both directions.`,
    `The screening standard still has to be written down before the listing goes live and applied identically to every adult applicant: verified income against a set threshold, prior landlords telephoned rather than emailed, employment confirmed, public-record review. Note too that Snellville offers a landlord no municipal backstop. The city states plainly that it "does not have a maintenance code requiring landlords to maintain certain living conditions," and directs tenant complaints to the state rather than handling them locally. There is no rental registration and no inspection regime — which cuts both ways, and puts the entire weight of the arrangement on the lease.`,
    `Because we hand the property back, the lease and the deposit file have to survive without us. Every adult occupant is named at signing, since a dispossessory only removes the people it names. The deposit is escrowed at a regulated institution and, since 2024, may not exceed two months' rent. The tenant receives a written condition list before the deposit is tendered — the document that makes any later deduction defensible — and the owner inherits the obligation to inspect within three business days of the tenancy ending and return the money within thirty days with the exact reasons for anything withheld.`,
  ],
};
